            }
          ]
        },
        "code": {
          "text": "Likely functional or diet-related dyspepsia / bloating with generalized mild abdominal discomfort"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "onsetString": "3–4 days"
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Condition/condition-2",
      "resource": {
        "resourceType": "Condition",
        "id": "condition-2",
        "clinicalStatus": {
          "coding": [
            {
